import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.sql.*;
import java.util.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import org.json.*;

@WebServlet("/api/users/*")
public class UserApiServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws IOException {
        String pathInfo = req.getPathInfo();
        String searchParam = req.getParameter("q");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");

        resp.setContentType("application/json");

        if (sortCol == null) sortCol = "username";
        if (direction == null) direction = "ASC";

        // Validate sort direction
        if (!direction.equalsIgnoreCase("ASC") && !direction.equalsIgnoreCase("DESC")) {
            direction = "ASC";
        }

        // Allowlist for sort columns - but sortCol is used in ORDER BY
        String[] allowedSorts = {"username", "email", "created_at", "last_login"};
        boolean validSort = false;
        for (String allowed : allowedSorts) {
            if (allowed.equalsIgnoreCase(sortCol)) {
                validSort = true;
                sortCol = allowed;
                break;
            }
        }
        if (!validSort) sortCol = "username";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query;
            ResultSet rs;

            if (searchParam != null && !searchParam.isEmpty()) {
                // Search mode - vulnerable to SQL injection
                String decodedSearch = URLDecoder.decode(searchParam, StandardCharsets.UTF_8.name());

                // "Sanitization" that can be bypassed
                decodedSearch = decodedSearch.replace("--", "");
                decodedSearch = decodedSearch.replace("/*", "");

                query = "SELECT id, username, email, role, created_at FROM users " +
                        "WHERE (username LIKE '%" + decodedSearch + "%' " +
                        "OR email LIKE '%" + decodedSearch + "%') " +
                        "ORDER BY " + sortCol + " " + direction;

                Statement stmt = conn.createStatement();
                rs = stmt.executeQuery(query);
            } else {
                query = "SELECT id, username, email, role, created_at FROM users " +
                        "ORDER BY " + sortCol + " " + direction + " LIMIT 50";
                Statement stmt = conn.createStatement();
                rs = stmt.executeQuery(query);
            }

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject user = new JSONObject();
                user.put("id", rs.getInt("id"));
                user.put("username", rs.getString("username"));
                user.put("email", rs.getString("email"));
                user.put("role", rs.getString("role"));
                user.put("created_at", rs.getString("created_at"));
                results.put(user);
            }

            JSONObject response = new JSONObject();
            response.put("results", results);
            response.put("count", results.length());
            resp.getWriter().write(response.toString());

        } catch (SQLException e) {
            JSONObject error = new JSONObject();
            error.put("error", "Database error");
            error.put("detail", e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write(error.toString());
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        // Admin endpoint for user creation
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) body.append(line);

        JSONObject input = new JSONObject(body.toString());
        String newUser = input.getString("username");
        String newEmail = input.getString("email");
        String newRole = input.optString("role", "viewer");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            PreparedStatement ps = conn.prepareStatement(
                "INSERT INTO users (username, email, role) VALUES (?, ?, ?)");
            ps.setString(1, newUser);
            ps.setString(2, newEmail);
            ps.setString(3, newRole);
            ps.executeUpdate();
            resp.setStatus(201);
            resp.getWriter().write("{\"status\":\"created\"}");
        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"" + e.getMessage() + "\"}");
        }
    }
}
